// The tools a routed subagent may be offered, and the tool.call guard that holds it to them. Claude Code builds a
// native subagent's tool pool from the context that spawned it, so a routed one is given no tool its caller lacks:
// its pool is what its agent type allows, less what the routed subagent that started it (`Route.parent`) is not
// allowed, up the chain to main, whose tools are the whole list. Pure over ports.
import { HANDBACK_TOOL, isFork, toolFilter } from './agents'
import { definitionOf } from './prompts'
import type { PromptsPort } from './prompts'
import type { RouteStore, StepIo } from './routing'
import type { Session } from './session'

// Whether the tool of a given name is one a routed subagent may be offered. It tests names alone, so main's
// tool list, which can change between steps, is read where the pool is used.
export type Pool = (tool: string) => boolean
type PoolIo = PromptsPort & Pick<RouteStore, 'route'>

// What a subagent is offered when the route of a subagent above it cannot be read: SubagentHandback, so it can
// still report, and nothing else. A pool built without that route could exceed the caller's.
const CLOSED: Pool = tool => tool === HANDBACK_TOOL.name

// The pool of `agentId` from its route (memory, else state) and the routes above it, or undefined when one of
// them is missing, native or loops. A pool is kept per agent until the agent is forgotten or the config is
// reloaded. A route read from state is not put in memory (a finished subagent above would be listed as routed
// again): only the pool drawn from it is kept.
async function derive(io: PoolIo, s: Session, agentId: string, above: ReadonlySet<string>): Promise<Pool | undefined> {
  const kept = s.pools.get(agentId)
  if (kept !== undefined) return kept
  const route = s.routes.get(agentId) ?? (await io.route(agentId))
  if (route === undefined || route.target == null || above.has(agentId)) return undefined
  const own = toolFilter(route.type, await definitionOf(io, s, route.type))
  const caller = route.parent === undefined ? undefined : await derive(io, s, route.parent, new Set([...above, agentId]))
  if (route.parent !== undefined && caller === undefined) return undefined
  // Claude Code offers a fork no SubagentHandback, so a fork's pool holds none.
  const hands = !isFork(route.type)
  const pool: Pool = tool => (tool === HANDBACK_TOOL.name ? hands : own(tool) && (caller?.(tool) ?? true))
  s.pools.set(agentId, pool)
  return pool
}

// The tools the routed subagent `agentId` may be offered: SubagentHandback, and the tools its type allows that
// the subagent which started it (if any) may be offered too. When a route above it cannot be read (it is in
// neither memory nor state, as after a reload that followed a refused write; it is native; or the chain loops),
// SubagentHandback alone, so a missing route never widens a pool; that pool is not kept, and the next step reads
// again. A rejected read of state is not caught: the step or the guard that asked fails and answers as it does
// for any internal error.
export async function poolOf(io: PoolIo, s: Session, agentId: string): Promise<Pool> {
  const pool = await derive(io, s, agentId, new Set())
  if (pool === undefined) io.debug(`styx pool ${agentId}: the route of a subagent above it cannot be read, so it is offered SubagentHandback alone`)
  return pool ?? CLOSED
}

// Denies a routed subagent a tool its last remote step did not offer: the engine would run it, since a
// subagent's tools are cut from main's by styx alone. Main and native agents pass. A routed agent with no
// offered set in memory (a hot reload emptied it) has its route read back from state and its set rebuilt
// from main's tools by its pool; it is denied when that cannot be done. An agent with no route in
// state is native, and kept in memory as such until it is forgotten, so its tool calls read no state again.
export async function guard(io: PoolIo & Pick<StepIo, 'list'>, s: Session, e: { tool: string; agentId?: string }): Promise<{ deny: string } | undefined> {
  if (e.agentId === undefined) return undefined
  // The engine is the authority on SubagentHandback: it runs or refuses the call itself.
  if (e.tool === HANDBACK_TOOL.name) {
    io.debug(`styx guard ${e.agentId} SubagentHandback passed to the engine`)
    return undefined
  }
  let offered = s.offered.get(e.agentId)
  if (offered === undefined) {
    const route = s.routes.get(e.agentId) ?? (await io.route(e.agentId)) ?? { target: null, label: 'native' }
    s.routes.set(e.agentId, route)
    if (route.target == null) return undefined
    const pool = await poolOf(io, s, e.agentId)
    offered = new Set([HANDBACK_TOOL.name, ...(await io.list()).map(t => t.name)].filter(pool))
    s.offered.set(e.agentId, offered)
  }
  const allowed = offered.has(e.tool)
  io.debug(`styx guard ${e.agentId} ${e.tool} ${allowed ? 'allowed' : 'denied'}`)
  return allowed ? undefined : { deny: `styx: ${e.tool} is not available to the ${s.routes.get(e.agentId)?.type ?? 'general-purpose'} subagent` }
}

// What the guard answers when it fails: a deny for a routed subagent or one styx has not cached (its route read
// may be what failed), so a failed check never lets a call through; undefined for main and for an agent known
// to be native, whose call goes on.
export function guardFailed(s: Session, e: { tool: string; agentId?: string }): { deny: string } | undefined {
  const routed = e.agentId !== undefined && (s.offered.has(e.agentId) || s.routes.get(e.agentId)?.target !== null)
  return routed ? { deny: `styx: could not check ${e.tool} for this subagent, so it was denied; retry, or see the debug log` } : undefined
}

files.hooks/prompts.ts:
// The system prompt of a routed step, and the model identity its transcript states. Main gets the prompt
// the engine composes for its own model, with the lines that name that model rewritten to name the routed
// model and provider. A built-in agent type gets the prompt styx writes for it (hooks/agents.ts); the `claude`
// type, which natively runs on main's own prompt, gets main's rewritten prompt; a custom agent type, or a
// built-in one with exactly one agent file naming it, gets the body of that file, and a custom one whose
// definition does not read runs as general-purpose.
// A subagent's prompt closes with the notes, its environment, how it hands back, and what answers it.
// `systemFor` is the one place a step's prompt is chosen. Pure over a port.
import type { Route } from '../types'
import { agentSystem, BUILTIN_AGENTS, BUILTIN_MODELS, BUILTIN_NOTES, builtinPrompt, dateOf, HANDBACK_TOOL, identityLine, isFork, NO_FRONTMATTER, NOT_REPRODUCED, parseAgentFile, parseInstalled, pluginRoot } from './agents'
import type { AgentDef, Parsed } from './agents'
import { own } from './config'
import type { ApiMessage } from './protocol'
import type { Session } from './session'

// One section of a composed system prompt: its id and its text.
type Section = { id: string; text: string }

export type PromptsPort = {
  // The sections of the prompt the engine composes for `model` with `tools` offered, in order.
  compose(model: string, tools: readonly string[]): Promise<readonly Section[]>
  cwd(): Promise<string>
  configDir(): Promise<string>
  exists(path: string): Promise<boolean>
  read(path: string): Promise<string>
  // The entries of a directory by name and kind (a symbolic link is `other`); none when it is not there.
  listDir(dir: string): Promise<readonly { name: string; kind: 'file' | 'dir' | 'other' }[]>
  // Runs a command to its end; a command that cannot start answers exit code 127.
  run(argv: readonly string[], opts?: { timeoutMs?: number }): Promise<{ exitCode: number; stdout: string; stderr: string }>
  now(): Promise<number>
  debug(text: string): void
}

const AGENT_NAME_RE = /^[A-Za-z0-9_-]{1,64}$/
const INHERIT = 'inherit'

// Says `text` once per session (a reload says it again): in /styx, and in the debug log. Its key is apart
// from the ones definitionOf logs under (`def <type>`).
function noteOnce(io: Pick<PromptsPort, 'debug'>, s: Session, key: string, text: string) {
  if (s.agentNotes.has(`note ${key}`)) return
  s.agentNotes.add(`note ${key}`)
  s.notes.push(text)
  io.debug(`styx ${text}`)
}

// --- model identity ------------------------------------------------------------------------------------------

// The sentence the engine states its own model in (section `env_info_model`, which 2.1.292 sends in the
// transcript as the session's model notice), with its knowledge cutoff; a knowledge-cutoff sentence alone; the
// environment's line on the latest Claude model family; and the sections that are nothing but the engine
// model's identity.
const POWERED_BY = /You are powered by the model (?:named [^\n]*?\. The exact model ID is \S+?|\S+?)\.(?=\s|$)(?: Assistant knowledge cutoff is [^\n]*?\.)?/g
const CUTOFF = / ?Assistant knowledge cutoff is [^\n]*?\./g
const FAMILY = /^.*The most recent Claude models\b.*(?:\n|$)/gm
const IDENTITY_SECTIONS = new Set(['fable_identity'])

// The composed main prompt for a routed model: `env_info_model` says `identity` in place of the engine
// model's, identity-only sections are left out, and the environment sections lose the engine model's
// knowledge cutoff and the Claude model-family line. Every other section is sent as composed. For a prompt
// that goes to a subagent working in another directory than the session's (`elsewhere`), the other
// environment sections are left out as well, since they may name the session's directory.
export function rewriteMain(sections: readonly Section[], identity: string, elsewhere = false): string {
  return sections
    .flatMap(x => {
      if (x.id === 'env_info_model') return [identity]
      if (IDENTITY_SECTIONS.has(x.id)) return []
      if (!x.id.startsWith('env_info')) return [x.text]
      if (elsewhere) return []
      const text = x.text.replace(POWERED_BY, identity).replace(CUTOFF, '').replace(FAMILY, '')
      return text.trim() === '' ? [] : [text]
    })
    .join('\n\n')
}

// A transcript as a routed model is sent it: the engine's notice of its own model, in a user message, names
// `model` served by `provider` instead. Messages without one are passed as they are.
export function withIdentity(messages: readonly ApiMessage[], model: string, provider: string): readonly ApiMessage[] {
  const identity = identityLine(model, provider)
  const fix = (text: string) => text.replace(POWERED_BY, identity)
  let changed = false
  const out = messages.map(m => {
    if (m.role !== 'user') return m
    if (typeof m.content === 'string') {
      const text = fix(m.content)
      if (text === m.content) return m
      changed = true
      return { ...m, content: text }
    }
    let hit = false
    const content = m.content.map(b => {
      const text = b.type === 'text' && typeof b['text'] === 'string' ? b['text'] : undefined
      const fixed = text === undefined ? undefined : fix(text)
      if (fixed === text) return b
      hit = true
      return { ...b, text: fixed }
    })
    if (!hit) return m
    changed = true
    return { ...m, content }
  })
  return changed ? out : messages
}

// --- custom agent types --------------------------------------------------------------------------------------

// `path` parsed by `parse`, read once per session: null when there is no file, an error when unreadable.
async function readParsed<T>(io: PromptsPort, s: Session, path: string, parse: (text: string) => Parsed<T>): Promise<Parsed<T> | null> {
  if (s.agentFiles.has(path)) return s.agentFiles.get(path) as Parsed<T> | null
  let value: Parsed<T> | null
  try {
    value = (await io.exists(path)) ? parse(await io.read(path)) : null
  } catch (err) {
    value = { error: `unreadable (${String(err)})` }
  }
  s.agentFiles.set(path, value)
  return value
}

// The `.claude/agents` directories of the project and of the configuration directory, in Claude Code's order.
const ownAgentDirs = async (io: PromptsPort) => [`${await io.cwd()}/.claude/agents`, `${await io.configDir()}/agents`]

// The agents directories Claude Code may read the definition of `type` from, in its order: a plugin agent
// `<plugin>:<name>` in its plugin's `agents`, any other in the session's `.claude/agents`, then in the
// configuration directory's `agents`. A plugin's directory is read off installed_plugins.json. `plugin` says
// which kind they are, because Claude Code reads the files of the two kinds by different rules.
async function agentDirs(io: PromptsPort, s: Session, type: string): Promise<Parsed<{ name: string; dirs: string[]; plugin: boolean }>> {
  const dir = await io.configDir()
  const cwd = await io.cwd()
  const colon = type.indexOf(':')
  const name = type.slice(colon + 1)
  if (!AGENT_NAME_RE.test(name)) return { error: `"${name}" is not an agent file name` }
  if (colon < 0) return { name, dirs: await ownAgentDirs(io), plugin: false }
  const file = `${dir}/plugins/installed_plugins.json`
  const installed = await readParsed(io, s, file, parseInstalled)
  if (installed === null) return { error: `${file}: no file` }
  if ('error' in installed) return { error: `${file}: ${installed.error}` }
  const root = pluginRoot(installed.plugins, type.slice(0, colon), cwd)
  if ('error' in root) return { error: `${file}: ${root.error}` }
  return { name, dirs: [`${root.root}/agents`], plugin: true }
}

// An agent file, with the name Claude Code knows its agent by: the frontmatter's `name`, else its file name less
// `.md`. `skipped` is why Claude Code ignores the file. In a `.claude/agents` directory it requires a `name` and a
// `description`, takes no agent from a file without either, and passes over a file with no frontmatter. A plugin's
// agent file needs neither field: its name falls back to the file name and its description to a default.
type AgentFile = { path: string; name: string; def: Parsed<AgentDef>; skipped?: string }
// How many entries styx lists in one agents directory and beneath it: a directory with more is one it cannot be
// sure to have read whole.
const AGENT_DIR_MAX = 128

// Every `*.md` file in the agents directory `dir`, in the directories beneath it too (Claude Code reads those),
// parsed and in path order; an error when a listing or the count fails. Read once per session. `plugin` says the
// directory is a plugin's, whose files Claude Code reads by the plugin rule (see AgentFile).
function agentFilesIn(io: PromptsPort, s: Session, dir: string, plugin: boolean): Promise<Parsed<AgentFile[]>> {
  const key = `agents ${dir}`
  let files = s.agentFiles.get(key) as Promise<Parsed<AgentFile[]>> | undefined
  if (files === undefined) s.agentFiles.set(key, (files = loadAgentDir(io, s, dir, plugin)))
  return files
}

async function loadAgentDir(io: PromptsPort, s: Session, dir: string, plugin: boolean): Promise<Parsed<AgentFile[]>> {
  try {
    const paths: string[] = []
    let seen = 0
    const walk = async (at: string) => {
      for (const entry of await io.listDir(at)) {
        if (++seen > AGENT_DIR_MAX) throw new Error(`more than ${AGENT_DIR_MAX} entries`)
        if (entry.kind === 'dir') await walk(`${at}/${entry.name}`)
        else if (entry.name.endsWith('.md')) paths.push(`${at}/${entry.name}`)
      }
    }
    await walk(dir)
    return await Promise.all(
      paths.sort().map(async path => {
        let def: Parsed<AgentDef>
        try {
          def = parseAgentFile(await io.read(path))
        } catch (err) {
          def = { error: `unreadable (${String(err)})` }
        }
        const missing = plugin || 'error' in def ? [] : (['name', 'description'] as const).filter(k => !def[k])
        const bare = !plugin && 'error' in def && def.error === NO_FRONTMATTER
        const skipped = bare ? 'no frontmatter' : missing.length === 0 ? undefined : `no ${missing.join(' or ')}`
        if (skipped !== undefined && !bare) noteOnce(io, s, `skipped ${path}`, `agents: ${path} has ${skipped}, which Claude Code requires of a file in .claude/agents, so it skips the file and so does styx`)
        return { path, name: ('error' in def ? undefined : def.name) || path.slice(path.lastIndexOf('/') + 1, -3), def, ...(skipped === undefined ? {} : { skipped }) }
      }),
    )
  } catch (err) {
    return { error: `${dir}: ${String(err)}` }
  }
}

// The agent files that name `type` (as its frontmatter `name`, whatever the file is called), in Claude Code's
// order of preference, the files among the others that styx could not read (any of them may define `type`
// under a name styx cannot see), and the directories they were looked for in.
async function definingFiles(io: PromptsPort, s: Session, type: string): Promise<Parsed<{ name: string; dirs: string[]; files: AgentFile[]; unread: AgentFile[] }>> {
  const found = await agentDirs(io, s, type)
  if ('error' in found) return found
  const files: AgentFile[] = []
  const unread: AgentFile[] = []
  for (const dir of found.dirs) {
    const listed = await agentFilesIn(io, s, dir, found.plugin)
    if ('error' in listed) return listed
    const kept = listed.filter(f => f.skipped === undefined)
    files.push(...kept.filter(f => f.name === found.name))
    unread.push(...kept.filter(f => f.name !== found.name && 'error' in f.def))
  }
  return { name: found.name, dirs: found.dirs, files, unread }
}

// A custom agent type's definition file: the first of the files that name it, which is the one Claude Code
// takes when no other of them is in play (see `contested`).
async function findDefinition(io: PromptsPort, s: Session, type: string): Promise<Parsed<{ def: AgentDef; path: string }>> {
  const found = await definingFiles(io, s, type)
  if ('error' in found) return found
  const [first] = found.files
  if (first === undefined) return { error: `no definition found (no agent file in ${found.dirs.join(' or ')} has the name ${found.name})` }
  return 'error' in first.def ? { error: `${first.path}: ${first.def.error}` } : { def: first.def, path: first.path }
}

// Whether Claude Code may define `type` from other than the one file styx reads, as far as styx can see: a type
// that more than one file names (it picks by a precedence styx does not follow). A file whose text does not read
// counts under its file name, since styx cannot tell it is not the definition; an agent that no file shows (an
// `--agents` or SDK one) is not seen.
export async function contested(io: PromptsPort, s: Session, type: string): Promise<boolean> {
  try {
    const found = await definingFiles(io, s, type)
    return 'error' in found || found.files.length > 1
  } catch {
    return true
  }
}

// The built-in agent type that runs on main's own system prompt (the engine's `appendSystemPrompt`).
const MAIN_PROMPT_TYPE = 'claude'

// A routed subagent's own definition when an agent file names its type and the definition reads, else
// undefined. Each type's outcome is logged once; a custom type whose definition does not read is also said in
// /styx, as it runs as general-purpose. A built-in type with no file, or with more than one, has no definition
// and says nothing: it runs on styx's own prompt. A built-in type with one file that reads says in /styx that it
// runs on that file; a file that does not read, and so may define one under a name styx cannot see, is said too. A
// fork has no definition of its own: it runs on its parent's prompt.
export async function definitionOf(io: PromptsPort, s: Session, type: string | undefined): Promise<AgentDef | undefined> {
  if (type === undefined || isFork(type)) return undefined
  const builtin = BUILTIN_AGENTS.includes(type)
  let single = false
  if (builtin) {
    try {
      const named = await definingFiles(io, s, type)
      if ('error' in named) return undefined
      for (const f of named.unread) {
        noteOnce(io, s, `unread ${f.path}`, `agents: ${f.path} cannot be read (${(f.def as { error: string }).error}); if it defines a built-in agent type, that type runs on styx's prompt instead of the file`)
      }
      if (named.files.length !== 1) return undefined
      single = true
    } catch {
      return undefined
    }
  }
  let found: Parsed<{ def: AgentDef; path: string }>
  try {
    found = await findDefinition(io, s, type)
  } catch (err) {
    found = { error: String(err) }
  }
  if (!s.agentNotes.has(`def ${type}`)) {
    s.agentNotes.add(`def ${type}`)
    io.debug('error' in found ? `styx agent-def ${type}: ${found.error}` : `styx agent-def ${type} from ${found.path}`)
    const unreadable = `agents: ${type} has ${single ? 'one agent file styx cannot read' : 'no readable definition'}`
    if ('error' in found) s.notes.push(single ? `${unreadable} (${found.error}); a plain call stays native and a styx agent call is refused` : `${unreadable} (${found.error}); it runs ${builtin ? `on ${type === MAIN_PROMPT_TYPE ? "main's" : "styx's"} prompt` : 'as general-purpose'}`)
    else if (builtin) s.notes.push(`agents: ${type} runs on ${found.path}, which overrides the built-in`)
  }
  return 'error' in found ? undefined : found.def
}

// Whether styx may run an agent type on a styx route, and whether its definition isolates it; else why not. Every
// route to a subagent on a styx model asks this, the plain Agent call under a routed parent (inherit.ts) and the
// styx agent tool alike, so the same call is answered the same from any conversation.
// A type styx cannot run itself (NOT_REPRODUCED) qualifies never. A fork qualifies always: it runs on its parent's
// prompt, and no agent file defines it. Any other built-in type qualifies when it inherits its parent's model:
// styx writes its prompt, or uses the one agent file that names it (`name: Explore`), whose model:, isolation: and
// tools then apply as a custom type's do. A custom type qualifies when its definition is one styx reads and names
// no model of its own. A custom type without a readable definition (a plugin loaded with --plugin-dir, an
// --agents or SDK agent, no agent file whose `name:` is the type) is left native, because styx would answer it with
// the general-purpose prompt and tools; so is a built-in type whose one agent file styx cannot read, and a type that more than one agent file names (`contested`).
// These back-offs keep a spawn the caller did not ask a model for native. `named` is a spawn whose caller named
// the styx model (a styx agent call): it starts on the parent's model whatever the definition says, so a type's
// own model and missing definition do not stop it.
// `fate` ends the debug line that says why.
export async function claimable(io: PromptsPort, s: Session, type: string, fate: string, named: boolean): Promise<{ isolated: boolean } | { no: string }> {
  if (isFork(type)) return { isolated: false }
  if (NOT_REPRODUCED.includes(type)) {
    io.debug(`styx inherit: ${type} is not a type styx can run; ${fate}`)
    return { no: 'is not a type styx can run' }
  }
  const builtin = BUILTIN_AGENTS.includes(type)
  const def = await definitionOf(io, s, type)
  // A built-in type that exactly one agent file names, and styx cannot read, may be defined by that file: not claimable.
  const files = builtin && def === undefined ? await definingFiles(io, s, type).catch(() => undefined) : undefined
  if (files !== undefined && !('error' in files) && files.files.length === 1 && 'error' in (files.files[0] as AgentFile).def) {
    io.debug(`styx inherit: ${type} has one agent file styx cannot read; ${fate}`)
    return { no: 'has one agent file styx cannot read' }
  }
  if (!builtin && def === undefined && !named) {
    io.debug(`styx inherit: ${type} has no readable definition; ${fate}`)
    return { no: 'has no readable definition' }
  }
  const model = def?.model ?? (builtin && def === undefined ? own(BUILTIN_MODELS, type) : undefined)
  if (!named && model !== undefined && model.trim().toLowerCase() !== INHERIT) return { no: 'names a model of its own' }
  // A named spawn of a custom type with no definition runs general-purpose whatever files name it.
  if (!(named && !builtin && def === undefined) && (await contested(io, s, type))) {
    io.debug(`styx inherit: ${type} has more than one definition (two agent files name it, or styx could not read them all); ${fate}`)
    return { no: 'has more than one definition' }
  }
  if (def?.isolation !== undefined && def.isolation !== 'worktree') {
    io.debug(`styx inherit: ${type} runs isolated as ${def.isolation}; ${fate}`)
    return { no: `runs isolated as ${def.isolation}` }
  }
  return { isolated: def?.isolation === 'worktree' }
}

// The agent type a styx agent call's `subagent_type` names, resolved as the engine resolves an Agent call's, for
// the styx agent tool's own spawn: `$.agent.spawn` takes a type only as exactly spelled, and every check and the
// route must use the type the engine runs. None is general-purpose. A type spelled exactly as a built-in type or
// an agent file's name is itself; another spelling is the one known type it matches ignoring case, and a spelling
// that matches more than one is denied with them listed. A plugin agent, and a type styx knows of no file for (an
// `--agents` or SDK agent), are passed on as they are, and the engine refuses a name that matches none.
export async function resolveType(io: PromptsPort, s: Session, type: string | undefined): Promise<{ type: string } | { deny: string }> {
  if (type === undefined || type === '') return { type: 'general-purpose' }
  if (BUILTIN_AGENTS.includes(type) || type.includes(':')) return { type }
  const known = new Set(BUILTIN_AGENTS.filter(t => !isFork(t)))
  for (const dir of await ownAgentDirs(io)) {
    const listed = await agentFilesIn(io, s, dir, false)
    if (!('error' in listed)) for (const f of listed) if (f.skipped === undefined) known.add(f.name)
  }
  if (known.has(type)) return { type }
  const fold = (t: string) => t.normalize('NFKC').toLowerCase()
  const matches = [...known].filter(k => fold(k) === fold(type)).sort()
  if (matches.length > 1) return { deny: `styx agent: subagent_type ${JSON.stringify(type)} matches more than one agent type (${matches.join(', ')}); name one of them exactly` }
  return { type: matches[0] ?? type }
}

// --- the prompt of a step ------------------------------------------------------------------------------------

// The platform as `uname -s` names it, lowercased (darwin, linux); undefined when it cannot be read.
async function platformOf(io: Pick<PromptsPort, 'run'>, s: Session): Promise<string | undefined> {
  if (s.platform === undefined) {
    const r = await io.run(['/usr/bin/uname', '-s'])
    const name = r.stdout.trim().toLowerCase()
    s.platform = r.exitCode === 0 && /^[a-z0-9_-]{1,32}$/.test(name) ? name : null
  }
  return s.platform ?? undefined
}

// What a step's prompt is chosen from: the agent file's definition when one names the type, the subagent's route
// (none for main), the engine model the main prompt is composed for, the routed target (`provider/model`),
// its model and provider, and the tools offered. For a fork these are its parent's: the nearest ancestor's route
// and definition that is not itself a fork (none when that is main), and `fork` says so.
type SystemInput = { def?: AgentDef; route?: Route; fork?: boolean; engineModel: string; target: string; model: string; provider: string; tools: readonly string[] }

// A routed step's system prompt and where it came from: `main` (the composed prompt, identity rewritten: main's
// own, and a `claude` subagent's when no agent file names it; one in a worktree is not told the session's
// directory), `custom` (an agent file's body: a custom type's, or a built-in type's that one file names) or
// `styx` (the prompt styx writes for a built-in type). A subagent's prompt is completed by agentSystem. A fork's is
// its parent's, as `fork of <source>`: a fork of main gets main's prompt alone, and a fork of a subagent that
// subagent's prompt less the handback guidance. Every fork is told how it reports in its messages (fork.ts), and
// Claude Code offers a fork no SubagentHandback, so no fork is told of it.
export async function systemFor(io: PromptsPort, s: Session, i: SystemInput): Promise<{ text: string; source: string }> {
  const fromMain = async (elsewhere = false) => rewriteMain(await io.compose(i.engineModel, i.tools), identityLine(i.model, i.provider), elsewhere)
  const handback = i.tools.includes(HANDBACK_TOOL.name)
  if (i.route === undefined) {
    const text = await fromMain()
    return { text, source: i.fork ? 'fork of main' : 'main' }
  }
  const type = i.route.type ?? 'general-purpose'
  const prompt =
    i.def !== undefined
      ? { body: i.def.prompt, source: 'custom', notes: BUILTIN_NOTES }
      : type === MAIN_PROMPT_TYPE
        ? { body: await fromMain(i.route.worktree !== undefined), source: 'main', notes: BUILTIN_NOTES }
        : { body: builtinPrompt(BUILTIN_AGENTS.includes(type) ? type : 'general-purpose', new Set(i.tools)), source: 'styx', notes: BUILTIN_NOTES }
  const text = agentSystem(prompt.body, {
    cwd: i.route.worktree?.path ?? (await io.cwd()),
    platform: await platformOf(io, s),
    date: dateOf(await io.now()),
    model: i.model,
    provider: i.provider,
    type,
    alias: i.route.label === i.target ? undefined : i.route.label,
    notes: prompt.notes,
    handback: handback && !i.fork,
  })
  return { text, source: i.fork ? `fork of ${prompt.source}` : prompt.source }
}

files.hooks/protocol.ts:
// The contract between the mod and the backend that answers its routed steps: what a step asks for, the
// events its answer streams back, and each provider's key state. Pure: no engine types and no I/O, so the
// helper process that serves steps imports it as the mod does.
import type { Effort } from '../types'
import type { JsonSchema } from './config'

// A transcript message as `$.session.messages({ as: "api" })` gives it: blocks, or (read as one text
// block) text.
export type ApiMessage = { role: 'user' | 'assistant'; content: string | readonly ({ type: string } & Record<string, unknown>)[] }
// A tool the remote model is offered: its name, description and input schema.
export type RemoteTool = { name: string; description: string; schema: JsonSchema }

// One routed step: its target (the alias or `provider/model` the route was made with, which the backend
// resolves against the config it holds), the system prompt, the tools offered, the transcript (a subagent's
// opening on its task), the effort the step asked for, and who asks (`main` or an agentId).
export type StepRequest = {
  target: string
  system: string
  tools: readonly RemoteTool[]
  transcript: readonly ApiMessage[]
  effort?: Effort | number
  who: string
}

// Why a response stopped, in the engine's words; `tool_use` when it ended on tool calls.
export type StopReason = 'end_turn' | 'max_tokens' | 'refusal' | 'tool_use'
// A response's tokens: input not read from cache, output, cache reads and writes, and the reasoning share
// of the output when the provider reports one.
export type Usage = { in: number; out: number; cacheRead: number; cacheWrite: number; reasoning?: number }
// How one step went: ms to the first response byte (null when none came) and in all, the request body's
// bytes, the prompt tokens (cache reads and writes included) and output tokens of a completed response (else null),
// its reasoning tokens, and the provider's finish reason as sent (`none` when it gave none, `error` when
// the step failed).
export type StepStats = { ttfbMs: number | null; totalMs: number; reqBytes: number; in: number | null; out: number | null; reasoning?: number; finish: string }

// One event of a step's answer, in order. `text` and `thinking` are deltas of the answer and the reasoning;
// a `tool_use` is a whole call with its input parsed, so a call cut short never appears. The events end
// with exactly one `stop` or `error`, then `stats`. An error's text is one line naming the cause and the
// fix: a `request` error had no usable response (not sent, refused, or cut in transit), a `response` error
// is one the response itself reported, or a response that broke its own format.
export type StepEvent =
  | { type: 'text'; text: string }
  | { type: 'thinking'; text: string }
  | { type: 'tool_use'; id: string; name: string; input: Record<string, unknown> }
  | ({ type: 'usage' } & Usage)
  | { type: 'stop'; reason: StopReason }
  | { type: 'error'; kind: 'request' | 'response'; text: string }
  | ({ type: 'stats' } & StepStats)

// A provider's key as the backend holds it: cached, not fetched yet (its helper has not run since the
// provider was approved), failed with that failure's line, or none (`auth: "none"`: no key, no helper).
export type ProviderStatus = { provider: string; key: 'cached' | 'not-run' | 'failed' | 'none'; failure?: string }

// What answers routed steps. `configure` takes a validated config's text and the fingerprints of the
// providers approved so far: a helper runs, and a key is kept, only for an approved provider. `start`, called
// in a hook the session outlives, binds the helper process to the session, and brings it up ahead of the
// first step when the config declares a provider, saying nothing when it cannot. `step` streams one step's
// events; aborting `signal` cancels its request. `status` reads key states and never runs a helper.
export type Backend = {
  configure(c: { configText: string; approved: readonly string[] }): Promise<void>
  start(): Promise<void>
  step(req: StepRequest, signal: AbortSignal): AsyncIterable<StepEvent>
  status(): Promise<readonly ProviderStatus[]>
}

// What the mod sends styxd, the helper process that serves steps, with every call: the session's token,
// the validated config text, the fingerprints approved so far, and the User-Agent of provider requests. A
// step adds its request, and is answered with one StepEvent per line.
export type Wire = { token: string; configText: string; approved: readonly string[]; userAgent?: string }
export type StepWire = Wire & { req: StepRequest }

// A step that failed before it could be answered: its one error, and the stats that end every step.
export const failedStep = (text: string, totalMs = 0): StepEvent[] => [
  { type: 'error', kind: 'request', text },
  { type: 'stats', ttfbMs: null, totalMs, reqBytes: 0, in: null, out: null, finish: 'error' },
]

// A tool-call id styx mints for a remote call: Anthropic-shaped, 35 characters, under OpenAI's 40.
export const mintToolId = () => `toolu_styx_${crypto.randomUUID().replaceAll('-', '').slice(0, 24)}`

files.hooks/routing.ts:
// Which model answers: main's per-turn pin and /model, each subagent's route, the remote step (the request
// it builds, its guards, its events as chunks, a styx agent call among them made an Agent call), and the
// failures that end a step. Pure over ports.
import type { CommandRunInput, CommandRunResult, ToolInfo, TurnStepChunk, TurnStepInput, TurnStepResult } from 'claude-code'

import type { Effort, MainPin, Route } from '../types'
import { FORK_REPORT, HANDBACK_TOOL, isFork } from './agents'
import { FORK_HISTORY, forkHistory, forkParent } from './fork'
import { advert, agentSchema } from './advert'
import { EFFORTS, inputBudget, isObject } from './config'
import type { Config, Target } from './config'
import { switched } from './leave'
import { explain, isStyxShaped, resolve } from './names'
import { poolOf } from './pool'
import { definitionOf, systemFor, withIdentity } from './prompts'
import type { PromptsPort } from './prompts'
import type { ApiMessage, Backend, RemoteTool, StepRequest } from './protocol'
import { firstLine, redact } from './redact'
import { SCHEMAS } from './schemas.gen'
import type { Assembler, Session, StepRecord } from './session'
import { translatedOf, translateUse, unclaimedFork, unstarted } from './spawn'
import type { AgentTypes } from './spawn'
import { createAssembler } from './step'
import { firstUserText, handbackState, withoutTool, withTask, withTranslated } from './transcript'
import { approve, ensureTrust, isTrusted } from './trust'
import type { TrustPort } from './trust'
import { labelOf, showStatus, shownTarget } from './ui'
import type { StatusPort } from './ui'

export const WRAPPER = 'mcp__styx__agent'
// Half of HookBudget.ms (10_000): both the module-promise await and $.clock.sleep spend the hook's budget.
const SPAWN_WAIT_MS = 5000
const TOOL_NAME_RE = /^[A-Za-z0-9_-]{1,64}$/

type Remote = Extract<Target, { kind: 'remote' }>
type StepResult = AsyncGenerator<TurnStepChunk, TurnStepResult>

export type Say = { toast(text: string): void; debug(text: string): void }
// What routing keeps in the engine's state: main's target and its pin for a turn, each subagent's route, and
// the Agent calls styx made of each conversation's styx agent calls (`who`: main, or an agentId).
export type RouteStore = {
  main(): Promise<string | null | undefined>
  setMain(target: string | null): Promise<void>
  pin(): Promise<MainPin | null | undefined>
  setPin(pin: MainPin): Promise<void>
  route(agentId: string): Promise<Route | undefined>
  setRoute(agentId: string, route: Route): Promise<void>
  translated(who: string): Promise<Readonly<Record<string, string>> | undefined>
  setTranslated(who: string, calls: Readonly<Record<string, string>>): Promise<void>
}
// The tools main has, and which of its MCP tools are loaded.
type ToolSource = { list(): Promise<readonly ToolInfo[]>; loadedMcp(): Promise<ReadonlySet<string>> }
// A conversation's transcript in the Messages API's form (main's, or an agent's), or why it cannot be read.
export type Transcripts = { transcript(agentId: string | undefined): Promise<readonly ApiMessage[] | { deny: string }> }
export type Sleeper = { sleep(ms: number, signal: AbortSignal): Promise<void> }
export type StepIo = Say & ToolSource & Transcripts & PromptsPort & Pick<TrustPort, 'trusted'>

const k = (n: number) => (n >= 1000 ? `${Math.round(n / 1000)}k` : String(n))
const stepKey = (e: Pick<TurnStepInput, 'agentId' | 'turnId' | 'index'>) => `${e.agentId ?? 'main'}:${e.turnId}:${e.index}`

// The alias names /model keeps from the native command while the config is broken: the last valid
// config's, and the broken file's own.
const knownAliases = (s: Session) => [...s.goodAliases, ...(s.loaded.declared ?? [])]

// --- main and subagent routes ----------------------------------------------------------------------------

// Selects main's target (null: native); when the target changes, forgets main's last remote prompt size and
// notes a route left (leave.ts).
// A selection holds once written. A clear holds in memory first, then in state, then on the status line;
// a rejected write of it is logged, not thrown: main stays native in this session, though a new session
// may read the old target back.
async function setMain(io: Pick<RouteStore, 'setMain'> & Pick<Say, 'debug'> & StatusPort, s: Session, target: string | null) {
  if (s.main === null && target === null) return
  if (target !== s.main) s.promptTokens.delete('main')
  if (target !== null) await io.setMain(target)
  switched(s, target)
  s.main = target
  if (target === null) {
    try {
      await io.setMain(null)
    } catch (err) {
      io.debug(`styx: could not persist clearing main (${String(err)}); main is native in this session`)
    }
  }
  showStatus(io, s)
}

// The main conversation's route for this step: fixed per turn at its first step and persisted, so a later
// selection or a reload never changes a turn already under way.
async function mainRoute(io: Pick<RouteStore, 'main' | 'pin' | 'setPin'>, s: Session, e: TurnStepInput): Promise<string | null> {
  if (s.pin?.turnId === e.turnId) return s.pin.target
  const persisted = await io.pin()
  if (persisted?.turnId === e.turnId) return (s.pin = persisted).target
  if (e.index > 0) return null
  if (s.main === undefined) s.main = (await io.main()) ?? null
  s.pin = { turnId: e.turnId, target: s.main }
  if (s.main !== null) s.routedTurns++
  await io.setPin(s.pin)
  return s.pin.target
}

// A subagent's route: memory, else (while a styx spawn is in flight) a bounded wait, else the persisted one; else, when
// the wait ran out with a spawn asked for on a styx target (or a fork under a routed parent) still starting, a route
// that refuses.
async function subRoute(io: Pick<RouteStore, 'route'> & Sleeper & AgentTypes & Pick<Say, 'debug'>, s: Session, agentId: string, signal: AbortSignal): Promise<Route | undefined> {
  const hit = s.routes.get(agentId)
  if (hit !== undefined) return hit
  let timedOut = false
  if (s.pendingSpawns.size > 0) {
    const ac = new AbortController()
    const outcome = await Promise.race([
      Promise.allSettled([...s.pendingSpawns]).then(() => 'settled'),
      io.sleep(SPAWN_WAIT_MS, AbortSignal.any([ac.signal, signal])).then(
        () => 'timeout',
        () => 'aborted',
      ),
    ])
    ac.abort()
    const after = s.routes.get(agentId)
    io.debug(`styx spawn-wait ${agentId} outcome=${outcome} routed=${after !== undefined}`)
    if (after !== undefined) return after
    timedOut = outcome === 'timeout'
  }
  const persisted = await io.route(agentId)
  if (persisted !== undefined) s.routes.set(agentId, persisted)
  return persisted ?? (timedOut ? (unstarted(s, agentId) ?? (await unclaimedFork(io, s, agentId))) : undefined)
}

// --- remote steps ----------------------------------------------------------------------------------------

// The tool names the `tool_reference` blocks of a transcript load: what ToolSearch returned to its caller.
function referencedTools(messages: readonly ApiMessage[]): Set<string> {
  const names = new Set<string>()
  const scan = (block: unknown) => {
    if (!isObject(block)) return
    if (block['type'] === 'tool_reference' && typeof block['tool_name'] === 'string') names.add(block['tool_name'])
    else if (block['type'] === 'tool_result' && Array.isArray(block['content'])) block['content'].forEach(scan)
  }
  for (const m of messages) if (typeof m.content !== 'string') m.content.forEach(scan)
  return names
}

// The tools a remote request offers: the non-MCP and loaded MCP tools `offered` keeps, the styx agent tool
// when the loop may call both Agent (which its calls become) and the tool itself (the tool list holds them
// and `offered` keeps them), and SubagentHandback to a subagent unless `noHandback` (a fork, which Claude Code offers
// none; a subagent the engine did not say it delivers through it; one the engine refused it; inside the cap). Each goes with its generated
// schema or a permissive one. An MCP tool is loaded when main's usage says so (`mainMcp`: main, or a fork of main,
// whose tools are main's: `$.tool.list()` and the usage are main's) or when the transcript sent holds a
// `tool_reference` to it, which is how a subagent loads one.
async function toolSet(io: ToolSource, s: Session, config: Config, t: Remote, isSub: boolean, mainMcp: boolean, noHandback: boolean, offered: (name: string) => boolean, referenced: ReadonlySet<string>): Promise<RemoteTool[]> {
  const handback = { name: HANDBACK_TOOL.name, description: HANDBACK_TOOL.description, schema: HANDBACK_TOOL.schema }
  // A model without tools is offered none, SubagentHandback included: its text-only end is handed back by styx (step.ts).
  if (!t.model.tools) return []
  const listed = await io.list()
  const loadedMcp = new Set([...(mainMcp ? await io.loadedMcp() : []), ...referenced])
  const tools: RemoteTool[] = []
  const seen = new Set<string>([HANDBACK_TOOL.name])
  const schemaless: string[] = []
  const long: string[] = []
  const wrapped = listed.some(x => x.name === 'Agent') && offered('Agent') && offered(WRAPPER)
  for (const tool of listed) {
    if (seen.has(tool.name)) continue
    seen.add(tool.name)
    if (tool.name === WRAPPER) {
      if (wrapped) tools.push({ name: WRAPPER, description: advert(config), schema: agentSchema(config, SCHEMAS['Agent'] ?? {}) })
      continue
    }
    if (!offered(tool.name)) continue
    if (tool.mcp && !loadedMcp.has(tool.name)) continue
    if (!TOOL_NAME_RE.test(tool.name)) {
      long.push(tool.name)
      continue
    }
    const schema = SCHEMAS[tool.name] ?? s.mcpSchemas[tool.name]
    if (schema === undefined) schemaless.push(tool.name)
    tools.push({ name: tool.name, description: tool.description, schema: schema ?? { type: 'object' } })
  }
  const cap = t.provider.maxTools
  const hands = isSub && !noHandback
  const room = hands ? cap - 1 : cap
  const kept = tools.slice(0, Math.max(0, room))
  s.toolReport = { schemaless, capped: tools.slice(Math.max(0, room)).map(x => x.name), long, cap }
  if (hands && cap > 0) kept.push(handback)
  return kept
}

// The tool that delivers a subagent step's failure as its report: SubagentHandback, when the step's request
// offers it (`offered`) and the subagent's transcript (`read`, else read here) says the engine delivers
// through it and shows no call of it refused since, so a run hands back at most once. A transcript that cannot be
// read cannot show a refusal, so styx's own record stands in: the first failure of a turn is handed back, and
// the failure of a later step of that turn, which the engine only runs after refusing the call, is not.
// Undefined for main and otherwise: the failure is then answered as text.
async function handbackFor(io: Transcripts, s: Session, e: TurnStepInput, offered: boolean, read?: unknown): Promise<string | undefined> {
  if (e.agentId === undefined || !offered) return undefined
  let messages: unknown
  try {
    messages = read ?? (await io.transcript(e.agentId))
  } catch {}
  if (Array.isArray(messages)) return handbackState(messages as ApiMessage[], HANDBACK_TOOL.name) === 'offered' ? HANDBACK_TOOL.name : undefined
  if (s.blindHandbacks.get(e.agentId) === e.turnId) return undefined
  s.blindHandbacks.set(e.agentId, e.turnId)
  return HANDBACK_TOOL.name
}

// Answers a step with `text` in place of a response, after whatever `assembler` has yielded: as text, or
// as one call of `handback` when it names one and no tool call was yielded.
async function* failStep(e: TurnStepInput, assembler: Assembler, text: string, handback?: string): StepResult {
  const end = assembler.end({ failure: text, ...(handback === undefined ? {} : { handback }) })
  yield* end.chunks
  return { turnId: e.turnId, index: e.index, answer: end.answer, toolUses: end.toolUses, stopReason: end.stopReason, usage: null }
}

async function* remoteStep(io: StepIo & Pick<RouteStore, 'route' | 'translated' | 'setTranslated'>, s: Session, backend: Backend, e: TurnStepInput, target: string, route: Route | undefined, signal: AbortSignal): StepResult {
  const key = stepKey(e)
  const record: StepRecord = { target }
  s.steps.set(key, record)
  const who = e.agentId ?? 'main'
  // A failure before the request is sent; a subagent's goes back through `handback` when it names one, and
  // is toasted (a main step's text is the answer already).
  const fail = async function* (text: string, handback: string | undefined) {
    s.steps.delete(key)
    if (e.agentId !== undefined) io.toast(text)
    return yield* failStep(e, createAssembler(target), text, handback)
  }
  // A fork is offered no SubagentHandback, so its failures are answered as text, its final message.
  const fork = isFork(route?.type)
  // A subagent styx started but could not run on the styx model its caller asked for hands that back as its report.
  if (route?.refused !== undefined) return yield* fail(route.refused, await handbackFor(io, s, e, !fork))
  const snap = s.loaded
  const t = snap.config === undefined ? undefined : resolve(snap.config, target)
  if (snap.config === undefined || t?.kind !== 'remote') {
    return yield* fail(
      `styx: ${target} is not available (${snap.errors[0] ?? 'no longer configured'}); the step was not sent. Fix ${snap.path}, run /styx reload, or pick another model`,
      await handbackFor(io, s, e, !fork),
    )
  }
  if (!(await isTrusted(io, t.provider))) {
    return yield* fail(`styx: provider ${t.provider.id} is not approved; run /model ${labelOf(snap.config, target)} to approve it. The step was not sent`, await handbackFor(io, s, e, !fork))
  }
  await approve(s, backend, t.provider)
  // A custom agent type's subagent gets its definition's prompt and tools, and so does a built-in type's that one
  // agent file names; any other built-in type's gets the prompt styx writes for it and the tools its type allows;
  // main the composed prompt; a fork its parent's prompt. Each names the routed model.
  const isSub = e.agentId !== undefined
  const read = await io.transcript(e.agentId)
  const forkBase = fork && route !== undefined ? await forkParent(io, s, route) : undefined
  if (fork && forkBase === undefined) return yield* fail(`styx: the route of the parent of this fork cannot be read; the step was not sent; retry`, undefined)
  // What the prompt is the prompt of: the route itself, or for a fork its parent's (undefined: main).
  const shape = forkBase === undefined ? route : forkBase.route
  const def = isSub ? await definitionOf(io, s, shape?.type) : undefined
  // Main keeps its own tools; only a subagent is cut from them: by its type, and by the subagent that started it.
  const pool = e.agentId === undefined ? () => true : await poolOf(io, s, e.agentId)
  // A fork is sent its parent's history joined to its own (fork.ts), told there how it reports; a fork whose history
  // cannot be rebuilt whole is not sent. The tool_reference blocks of that history load MCP tools.
  const history =
    'deny' in read
      ? undefined
      : fork && route !== undefined
        ? await forkHistory(io, s, who, route, read, WRAPPER, [FORK_REPORT])
        : withTranslated(e.agentId === undefined ? read : withTask(read, route?.prompt), await translatedOf(io, s, who), WRAPPER)
  const referenced = history === undefined ? new Set<string>() : referencedTools(history)
  // A subagent is offered SubagentHandback only while the engine's transcript says it delivers through it (in 2.1.294,
  // only in auto permission mode) and no call of it has been refused since; else its final text is its report. A
  // `tools: false` subagent is offered none: styx hands its final text back as the call (`synth`).
  const synth = isSub && !fork && !t.model.tools
  const state = !isSub ? 'unsaid' : 'deny' in read ? 'offered' : handbackState(read, HANDBACK_TOOL.name)
  if (isSub && !fork && state !== 'offered' && (s.offered.get(who)?.has(HANDBACK_TOOL.name) ?? true)) io.debug(`styx: ${who} is offered no SubagentHandback (${state === 'unsaid' ? 'the engine did not say it delivers through it; its final text is its report' : 'the engine refused a call of it'})`)
  const tools = await toolSet(io, s, snap.config, t, isSub, !isSub || (fork && forkBase?.route === undefined), fork || state !== 'offered', pool, referenced)
  const names = tools.map(x => x.name)
  if (e.agentId !== undefined) s.offered.set(e.agentId, new Set(names))
  const prompt = await systemFor(io, s, { def, route: shape, fork: forkBase !== undefined, engineModel: e.model, target: t.target, model: t.model.id, provider: t.provider.id, tools: names })
  const handback = await handbackFor(io, s, e, names.includes(HANDBACK_TOOL.name) || synth, read)
  if ('deny' in read) return yield* fail(`styx: the transcript of ${who} is unreadable (${read.deny}); the step was not sent; retry`, handback)
  if (history === undefined) return yield* fail(FORK_HISTORY, handback)
  const messages = withIdentity(t.model.tools ? history : withoutTool(history, HANDBACK_TOOL.name), t.model.id, t.provider.id)
  io.debug(
    `styx req ${who} msgs=${messages.length} firstUser=${JSON.stringify(redact(firstUserText(messages)).slice(0, 60))} tools=${tools.length}[${tools
      .slice(0, 8)
      .map(x => x.name)
      .join('|')}]`,
  )
  // The styx agent call's effort, else the level a custom agent's definition declares, else the step's own.
  const declared = def?.effort !== undefined && EFFORTS.includes(def.effort as Effort) ? (def.effort as Effort) : undefined
  const effort = route?.effort ?? declared ?? e.effort
  const req: StepRequest = { target, system: prompt.text, tools, transcript: messages, ...(effort === undefined ? {} : { effort }), who }
  const budget = inputBudget(t.model, t.provider.kind)
  // The last response's prompt size counts while the transcript has not shrunk since (a /compact shrinks it);
  // else the request's own size.
  const last = s.promptTokens.get(who)
  const estimate = last !== undefined && e.messageCount >= last.messageCount ? last.tokens : Math.ceil(JSON.stringify(req).length / 3.5)
  if (estimate > 0.95 * budget) {
    const toolTokens = Math.ceil(JSON.stringify(tools).length / 3.5)
    return yield* fail(
      toolTokens > 0.5 * budget
        ? `styx: tool schemas alone take ~${k(toolTokens)} of ${target}'s ${k(budget)} input budget; set "tools": false on the model or use a larger one`
        : `styx: context ~${k(estimate)} exceeds ${target}'s ${k(budget)} input budget; run /compact`,
      handback,
    )
  }
  const assembler = createAssembler(t.target)
  record.assembler = assembler
  for await (const ev of backend.step(req, signal)) {
    if (ev.type === 'stats') {
      s.lastSteps.delete(who)
      s.lastSteps.set(who, { target, stats: ev, prompt: prompt.source })
    }
    yield* assembler.feed(ev.type === 'tool_use' && ev.name === WRAPPER ? await translateUse(io, s, who, target, ev, names.includes(WRAPPER)) : ev)
  }
  // A subagent offered SubagentHandback hands a request failure back as its report, so its run ends with
  // the failure delivered rather than re-asked; after a refused handback it answers text, and the run ends.
  const end = assembler.end({ ...(handback === undefined ? {} : { handback }), ...(synth ? { deliver: true } : {}) })
  if (end.delivered === true) io.debug(`styx: ${who} ended on text; styx handed it back as one ${HANDBACK_TOOL.name} call (tools: false)`)
  const stop = end.chunks.pop() as TurnStepChunk
  yield* end.chunks
  const u = end.usage
  if (u !== null) s.promptTokens.set(who, { tokens: u.input_tokens + u.cache_read_input_tokens + u.cache_creation_input_tokens, messageCount: e.messageCount })
  if (end.failure !== undefined && e.agentId !== undefined) io.toast(firstLine(end.failure))
  const result: TurnStepResult = { turnId: e.turnId, index: e.index, answer: end.answer, toolUses: end.toolUses, stopReason: end.stopReason, usage: end.usage }
  yield stop
  s.steps.delete(key)
  return result
}

// A turn.step: native when no styx target holds it, else the remote step. `native` is the step beneath.
export async function* turnStep(io: StepIo & Pick<RouteStore, 'main' | 'pin' | 'setPin' | 'route' | 'translated' | 'setTranslated'> & Sleeper & AgentTypes, s: Session, backend: Backend, e: TurnStepInput, signal: AbortSignal, native: () => StepResult): StepResult {
  const route = e.agentId === undefined ? undefined : await subRoute(io, s, e.agentId, signal)
  const target = e.agentId === undefined ? await mainRoute(io, s, e) : (route?.target ?? null)
  if (target === null) return yield* native()
  return yield* remoteStep(io, s, backend, e, target, route, signal)
}

// A turn.step whose hook failed (`error`): a step styx routes is answered with the internal-error text,
// handed back when it is a subagent's, and never passed to another model; any other goes on beneath.
export async function* stepFailed(io: Say & Transcripts, s: Session, e: TurnStepInput, error: { kind: string; message?: string }, native: () => StepResult): StepResult {
  const key = stepKey(e)
  const record = s.steps.get(key)
  const target = record?.target ?? (e.agentId !== undefined ? (s.routes.get(e.agentId)?.target ?? null) : s.pin?.turnId === e.turnId ? s.pin.target : (s.main ?? null))
  try {
    io.debug(`styx: turn.step ${key} failed (${error.kind}: ${error.message ?? ''}); ${target === null ? 'passed to the native model' : `answered with the internal-error text for ${target}`}`)
  } catch {}
  if (target === null) return yield* native()
  s.steps.delete(key)
  const handback = await handbackFor(io, s, e, !isFork(s.routes.get(e.agentId ?? '')?.type))
  return yield* failStep(e, record?.assembler ?? createAssembler(target), `styx: internal error on ${target}; the step was not sent to another model (see the debug log)`, handback)
}

// --- /model ----------------------------------------------------------------------------------------------

export type ModelPort = TrustPort & Pick<RouteStore, 'setMain'> & Pick<Say, 'debug'> & StatusPort & { contextTokens(): Promise<number> }

// /model: a styx alias or `provider/model` selects main's target, one line and no toast; any other argument
// goes to the native command (`next`), and leaves styx when styx held main.
export async function modelCommand(io: ModelPort, s: Session, e: CommandRunInput, next: (e: CommandRunInput) => Promise<CommandRunResult>): Promise<CommandRunResult> {
  const withLine = (text: string | undefined, line: string) => (text ? `${text}\n${line}` : line)
  const leaving = () => (s.main ? `styx: left ${shownTarget(s.loaded.config, s.main)}` : undefined)
  // The native /model with `args`, then main cleared; its output says so when styx held main.
  const native = async (args: string) => {
    const left = leaving()
    const r = await next({ ...e, args })
    await setMain(io, s, null)
    return left === undefined ? r : { ...r, text: withLine(r.text, left) }
  }
  const arg = e.args.trim()
  if (arg === '') {
    // The picker. Its pick lands after `next(e)` resolves, so styx leaves before opening it: a pick, an
    // unchanged pick and Esc all leave styx alike, and /model <alias> returns to the alias.
    const left = leaving()
    if (left !== undefined) await setMain(io, s, null)
    const r = await next(e)
    return left === undefined ? r : { ...r, text: withLine(r.text, left) }
  }
  const snap = s.loaded
  if (snap.missing || !isStyxShaped(snap.config, arg, knownAliases(s))) return native(e.args)
  if (snap.config === undefined && arg.startsWith('native/') && arg.length > 'native/'.length) return native(arg.slice('native/'.length))
  if (snap.config === undefined) return { text: `styx: can't switch to ${arg}: config error, ${snap.errors[0]}. Native model unchanged; fix ${snap.path}, then run /styx reload` }
  const t = resolve(snap.config, arg)
  if (t === undefined) return { text: explain(snap.config, arg) }
  if (t.kind === 'native') return native(t.model)
  if (!(await ensureTrust(io, t.provider))) return { text: `styx: provider ${t.provider.id} not approved; native model unchanged. Run /model ${arg} again and choose Allow` }
  const context = Math.max(await io.contextTokens(), s.promptTokens.get('main')?.tokens ?? 0)
  const budget = inputBudget(t.model, t.provider.kind)
  if (context > 0.85 * budget) return { text: `styx: transcript ~${k(context)} tokens exceeds ${t.target}'s ${k(budget)} input budget; run /compact, then /model ${arg}` }
  await setMain(io, s, t.label)
  return { text: `Set model to ${t.label === t.target ? t.target : `${t.label} (${t.target})`}` }
}

// When /model fails inside styx: a styx-shaped argument is answered, the native command not run; any other
// goes on beneath (`next`), and so does a failure after `next` was called.
export function modelFailed(s: Session, e: CommandRunInput, called: boolean, next: (e: CommandRunInput) => Promise<CommandRunResult>): Promise<CommandRunResult> | CommandRunResult {
  return called || s.loaded.missing || !isStyxShaped(s.loaded.config, e.args.trim(), knownAliases(s))
    ? next(e)
    : { text: `styx: couldn't switch to ${e.args.trim()} (internal error; see the debug log). Native model unchanged` }
}

// A model switch made outside /model (the /config Model row, the SDK) leaves styx too: main is cleared, and
// the status line says so.
export async function modelSwitched(io: Pick<RouteStore, 'setMain'> & Pick<Say, 'debug'> & StatusPort, s: Session, source: string) {
  if ((source === 'command' || source === 'picker' || source === 'sdk') && s.main) await setMain(io, s, null)
}

